fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn body<'a>(text:&'a str,name:&str)->&'a str{let start=text.find(&format!("fn {name}")).unwrap();let open=start+text[start..].find('{').unwrap();let mut depth=1;let mut end=open+1;for c in text[end..].chars(){end+=c.len_utf8();if c=='{'{depth+=1;}else if c=='}'{depth-=1;}if depth==0{break;}}&text[open..end]}
fn compact(s:&str)->String{s.chars().filter(|c|!c.is_whitespace()).collect()}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){
 let mut entries:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();entries.sort();
 for p in entries {let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();
  if s.starts_with("target-") {continue;}
  if p.is_dir(){archive(root,&p,dest,index);continue;}
  if s.starts_with("candidate/") && ![
   "candidate/crates/zopro-core/src/msm.rs","candidate/crates/zopro-core/src/msm_affine.rs",
   "candidate/crates/zopro-core/src/msm_affine/fused_kh.rs","candidate/crates/zopro-core/src/msm_affine/borrowed_pending.rs"
  ].contains(&s.as_str()){continue;}
  if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|e|p.extension().is_some_and(|x|x==*e)){continue;}
  let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);
 }
}
